function resetToHome() {
    clearInterval(timerInterval);
    const gameScreen = document.getElementById('screen-game');
    const wasInGame = gameScreen && !gameScreen.classList.contains('hidden');

    if (!wasInGame) {
        try { sessionStorage.removeItem('agreesy_passplay_name'); } catch (e) {}
        updateProfileUI();
        partnerLikes = null;
        partnerRoundCardIds = null;
        completedPlayers = [];
        currentDeckId = null;
        activeRoundCards = [];
        window.history.replaceState(null, null, '/');
    }
    const banner = document.getElementById('p2-welcome-banner');
    if (banner) banner.classList.add('hidden');
    renderDeckList();
    updateHeroRoundCardUI();
    showScreen('screen-home');
}

function isAnyModalOpen() {
    return ['modal-profile', 'modal-pwa-install', 'modal-site-share', 'modal-legal', 'roulette-modal', 'modal-pass-play', 'modal-food-picker', 'modal-timeout']
        .some(id => {
            const el = document.getElementById(id);
            return el && !el.classList.contains('hidden');
        });
}

function hidePwaBannerTemp() {
    const banner = document.getElementById('pwa-install-banner');
    if (banner) banner.classList.add('hidden');
}

function resetConfettiSafe() {
    if (typeof confetti === 'function' && typeof confetti.reset === 'function') {
        confetti.reset();
    }
}

function showScreen(screenId) {
    if (typeof closeTimeoutModal === 'function') closeTimeoutModal();
    [
        'screen-home',
        'screen-custom',
        'screen-game',
        'screen-share',
        'screen-p1-zero',
        'screen-solo-duel',
        'screen-match',
        'screen-nomatch',
        'screen-chores-result'
    ].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.classList.add('hidden');
    });
    const target = document.getElementById(screenId);
    if (target) target.classList.remove('hidden');

    if (screenId !== 'screen-home') {
        hidePwaBannerTemp();
    }
    if (screenId !== 'screen-match') {
        resetConfettiSafe();
    }
    const footerEl = document.getElementById('app-footer');
    if (footerEl) {
        if (['screen-game', 'screen-solo-duel', 'screen-custom'].includes(screenId)) {
            footerEl.classList.add('hidden');
        } else {
            footerEl.classList.remove('hidden');
        }
    }
}

/**************************************************************
 * 8. TOUCH SWIPE GESTURES (Apple Fluid Physics & Dynamic Drag)
 **************************************************************/
function initTouchSwipe() {
    const cardEl = document.getElementById('active-card');
    if (!cardEl) return;
    let startX = 0;
    let startY = 0;
    let currentX = 0;
    let isDragging = false;

    cardEl.addEventListener('touchstart', (e) => {
        if (!e.touches || e.touches.length === 0) return;
        startX = e.touches[0].screenX;
        startY = e.touches[0].screenY;
        currentX = startX;
        isDragging = true;
        cardEl.style.transition = 'none';
    }, { passive: true });

    cardEl.addEventListener('touchmove', (e) => {
        if (!isDragging || !e.touches || e.touches.length === 0) return;
        currentX = e.touches[0].screenX;
        const currentY = e.touches[0].screenY;
        const dx = currentX - startX;
        const dy = currentY - startY;

        // Apple fluid rotation & translation
        const rotation = (dx * 0.07).toFixed(2);
        cardEl.style.transform = `translate3d(${dx}px, ${dy * 0.25}px, 0) rotate(${rotation}deg)`;

        // Tactile glow feedback
        if (dx > 25) {
            cardEl.style.boxShadow = `0 20px 45px rgba(16, 185, 129, ${Math.min(0.45, dx / 200)})`;
        } else if (dx < -25) {
            cardEl.style.boxShadow = `0 20px 45px rgba(244, 63, 94, ${Math.min(0.45, Math.abs(dx) / 200)})`;
        } else {
            cardEl.style.boxShadow = '';
        }
    }, { passive: true });

    cardEl.addEventListener('touchend', () => {
        if (!isDragging) return;
        isDragging = false;
        const dx = currentX - startX;

        if (Math.abs(dx) > 65) {
            // Apple spring exit animation
            cardEl.style.transition = 'transform 0.28s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.28s ease';
            cardEl.style.transform = dx > 0 
                ? 'translate3d(120vw, 20px, 0) rotate(22deg)' 
                : 'translate3d(-120vw, 20px, 0) rotate(-22deg)';
            cardEl.style.opacity = '0';
            setTimeout(() => {
                cardEl.style.transition = '';
                cardEl.style.transform = '';
                cardEl.style.opacity = '1';
                cardEl.style.boxShadow = '';
                handleSwipe(dx > 0);
            }, 250);
        } else {
            // Spring bounce back to center
            cardEl.style.transition = 'transform 0.35s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.3s ease';
            cardEl.style.transform = 'translate3d(0, 0, 0) rotate(0deg)';
            cardEl.style.boxShadow = '';
            setTimeout(() => {
                cardEl.style.transition = '';
            }, 350);
        }
    }, { passive: true });
}

